import { assetUrl } from "./assets"

// Trigger recommendations derived from the systematic-review annotations.
// The summary is generated by scripts/buildTriggerRecommendations.mjs.

export interface SummaryPattern { relation: string; event: string; count: number }
export interface SummaryEntry { total: number; medianDuration: number | null; patterns: SummaryPattern[] }
export interface RecommendationSummary {
  source: string
  generatedAt: string
  videos: number
  annotations: number
  byData: Record<string, SummaryEntry>
}

export interface RecommendationPattern { text: string; count: number; percent: number }
export interface Recommendation {
  labels: string[]
  total: number
  patterns: RecommendationPattern[]
  medianDuration: number | null
}

// The authoring tool's data names mapped onto the review's data labels.
export const DATA_NAME_TO_REVIEW_LABELS: Record<string, string[]> = {
  elapsedTime: ["elapsed time of race"],
  raceName: ["race name"],
  nationality: ["nation flag", "nation abbr", "nation full name"],
  swimmerName: ["full first name", "abbr first name", "full last name", "abbr last name"],
  currentSpeed: ["speed"],
  ranking: ["ranking number"],
  distanceSwum: ["distance swam", "distance of current laps"],
  lapDistance: ["distance of current laps"],
  distanceToLeader: ["others' distance differerences to leader"],
  worldRecord: ["wr (world record)", "wr (world record) splitted", "time difference of the leader to wr", "time difference of the leader to wr (splitted)"],
  olympicRecord: ["cr (competition record)", "cr (competition record) splitted", "time difference of the leader to cr", "time difference of the leader to cr (splitted)"],
  differenceRecordAndLeader: ["time difference of the leader to wr", "time difference of the leader to wr (splitted)", "time difference of the leader to cr", "time difference of the leader to cr (splitted)"],
  leaderLaneNumber: ["lane number"],
  distanceDived: ["distance diving"],
  reaction: ["reaction time"],
}

const RELATION_WORD: Record<string, string> = {
  after: "after",
  before: "before",
  during: "during",
  "after+before": "before or after",
  "after+before+during": "around",
  "after+during": "during and after",
  "before+others": "before",
  others: "around",
  unspecified: "around",
}

const EVENT_WORD: Record<string, string> = {
  turning: "a turn",
  "race start": "the race start",
  "race end": "the race end",
  "general swimming": "general swimming",
  "overtake (in relay)": "an overtake (relay)",
  lap: "a lap",
  "whole race": "the whole race",
  "jump into the water": "the dive",
  "last lane": "the last lap",
  others: "other events",
  unspecified: "unspecified events",
}

export function patternText(relation: string, event: string) {
  const r = RELATION_WORD[relation] ?? relation.replace(/\+/g, " and ")
  const e = EVENT_WORD[event] ?? event
  return `${r} ${e}`
}

// Merge the review entries of every label mapped to `dataName` and rank
// the (relation, event) patterns. Returns null when the review has no data
// for this kind of visualization.
export function buildRecommendation(dataName: string | undefined, summary: RecommendationSummary | null, maxPatterns = 3): Recommendation | null {
  if (!dataName || !summary) return null
  const labels = (DATA_NAME_TO_REVIEW_LABELS[dataName] ?? []).filter((l) => summary.byData[l])
  if (labels.length === 0) return null
  const counts = new Map<string, number>()
  const durations: number[] = []
  let total = 0
  for (const label of labels) {
    const entry = summary.byData[label]
    total += entry.total
    for (const p of entry.patterns) {
      const key = patternText(p.relation, p.event)
      counts.set(key, (counts.get(key) ?? 0) + p.count)
    }
    if (entry.medianDuration !== null) durations.push(entry.medianDuration)
  }
  if (total === 0) return null
  const patterns = [...counts.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, maxPatterns)
    .map(([text, count]) => ({ text, count, percent: Math.round((count / total) * 100) }))
  const medianDuration = durations.length ? Math.round((durations.reduce((a, b) => a + b, 0) / durations.length) * 10) / 10 : null
  return { labels, total, patterns, medianDuration }
}

let cache: Promise<RecommendationSummary | null> | null = null

export function loadRecommendationSummary(): Promise<RecommendationSummary | null> {
  if (!cache) {
    cache = fetch(assetUrl("labelTool/trigger-recommendations.json"))
      .then((r) => (r.ok ? (r.json() as Promise<RecommendationSummary>) : null))
      .catch(() => null)
  }
  return cache
}
